update content_bodies set title = 'いつかの日常が蘇る場所　茂木町', description = '懐かしい「あの頃」がそのまま残る、茂木町。
たまにはいつもの日常から離れて、昭和の情緒を感じに来ませんか。
いつもの調子で進まない生活。でも、ここでは急ぐ必要はありません。

「便利じゃないけど、心地よく温かい」

そんな空気を味わうために、そんな時代に思いを馳せに、栃木県茂木町へ。

