update content_bodies set title = '【絶景茨城】牛久大仏 ［4K］茨城県牛久市｜VISIT IBARAKI,JAPAN', description = '牛久大仏は、浄土真宗東本願寺派本山東本願寺が事業主体。この浄土真宗の開祖が、親鸞聖人（1173年～1262年）です。親鸞は後鳥羽上皇の怒りを買い、1207年に越後国に流罪に処せられます。その4年後に赦免された後、常陸国（現在の茨城県）に入り、関東における布教の拠点としました。県内には親鸞ゆかりの寺や事跡が多く残っており、この牛久の地もそのひとつです。
事業構想は1983年に着手、1986年に工事が着工し、1992年12月に完成した。事業主体は浄土真宗東本願寺派本山東本願寺。
その姿は同派の本尊である阿弥陀如来像の形状を拡大したものである。
全高120m（像高100m、台座20m）を誇り、奈良の大仏（像高14.98m）が掌に乗り、アメリカ合衆国ニューヨーク州にある自由の女神像（全高93m、手を掲げた姿勢の像高さ46.05m）の実質的な像高（足元から頭頂までの高さ33.86m）の3倍近くの大きさである。

※未許可でのドローン使用は禁止されています。

牛久大仏
https://daibutu.net/index.html

絶景茨城
