update content_bodies set title = '[Spectacular Ibaraki] Ushiku Daibutsu [4K] Ushiku City, Ibaraki Prefecture | VISIT IBARAKI, JAPAN', description = 'The Ushiku Daibutsu is a project initiated by the Higashi Honganji sect of Jodo Shinshu. The founder of this Jodo Shinshu sect is Shinran Shonin (1173-1262). Shinran incurred the wrath of Emperor Go-Toba and was exiled to Echigo Province in 1207. Four years later, after being pardoned, he entered Hitachi Province (now Ibaraki Prefecture) and established a base for propagation in the Kanto region. Many temples and historical sites related to Shinran remain in the prefecture, and this area of Ushiku is one of them.
The project began in 1983, construction started in 1986, and it was completed in December 1992. The project was led by the Higashi Honganji sect of Jodo Shinshu.
Its form is an enlarged version of the Amida Nyorai statue, which is the principal object of worship of this sect.
Standing at a total height of 120 meters (100 meters for the statue and 20 meters for the pedestal), it is nearly three times the height of the Great Buddha of Nara (which is 14.98 meters tall) and the effective height of the Statue of Liberty in New York, USA (which has a total height of 93 meters and an effective statue height of 33.86 meters from feet to top of the head).

*Unauthorized use of drones is prohibited.

Ushiku Daibutsu
https://daibutu.net/index.html

Spectacular Ibaraki
https://www.youtube.com/playlist?list=PLTFO1tp2jqZ0XUg99QVYMQSlWqKaRurju

Visit Ibaraki, Japan
https://www.youtube.com/playlist?list=PLTFO1tp2jqZ3UCGvINWxTmZhTLgLzOPPM' where id = 'WqmyX6eiPodnPuFv06oaN';
update content_bodies set title = '【絶景茨城】百段階段ひなまつり-茨城県久慈郡大子町｜VISIT IBARAKI,JAPAN', description = '茨城県大子町十二所神社の参道にある百段階段を舞台に毎年開催される「百段階段でひなまつり」

全国から提供されたひな人形は様々な歴史がつまっておりひとつひとつに個性が溢れます。

レトロな街並みが残る商店街にも各商店や民家の軒先に段飾りや雛飾りが並びます。

また、同日には駅前通りで花嫁行列が行われ実際に結婚された新郎新婦が街の中を練り歩きます。

