update content_bodies set title = '[Spectacular Ibaraki] Hyakudankaidan Hina Matsuri - Daigo Town, Kuji District, Ibaraki Prefecture | VISIT IBARAKI, JAPAN', description = 'The ''Hina Matsuri at Hyakudankaidan'' is held every year on the hundred-step staircase at Juunishoshrine in Daigo Town, Ibaraki Prefecture.

The hina dolls provided from all over the country are filled with various histories, and each one has its own unique personality.

In the retro shopping district, tiered displays and hina decorations line the eaves of various shops and houses.

Additionally, on the same day, a bridal procession takes place on the street in front of the station, where newlyweds who have actually gotten married walk through the town.

