update content_bodies set title = '【絶景茨城】ハス田｜VISIT IBARAKI,JAPAN', description = 'れんこん生産量日本一を誇る茨城県では、7月から8月にかけて霞ヶ浦周辺に広がる蓮の花が見られます。広大な湖のそばに咲き誇る蓮の花は、湖面に輝く太陽の光と共に人々を魅了します。

秋になると葉は茶色になり枯れ始めます。
れんこんの収穫では、れんこんを浮かび上がらせる「水掘り」を採用。れんこんの肌を傷つけないよう、掘り上げてから丁寧に泥を洗い落とします。ぷっくりとした団子状で柔らかな肉質、ほんのりとした甘みが魅力です。

霞ヶ浦の豊富な水資源と肥沃な土という自然条件により、日本中で愛される美味しいれんこんが育まれています。

#霞ヶ浦 #れんこん #ハス #茨城' where id = 'S1AnfJIBnIJmMDp7JQyQa';
update content_bodies set title = '[Spectacular Ibaraki] Lotus Fields | VISIT IBARAKI, JAPAN', description = 'In Ibaraki Prefecture, which boasts the highest production of lotus root in Japan, lotus flowers can be seen blooming around Lake Kasumigaura from July to August. The lotus flowers blooming beside the vast lake captivate people with the sunlight shimmering on the water''s surface.

In autumn, the leaves turn brown and begin to wither.
During the harvesting of lotus root, a method called "water digging" is employed to bring the lotus roots to the surface. Care is taken to wash off the mud gently after digging them up to avoid damaging the skin of the lotus root. Their plump, round shape and soft texture, along with a hint of sweetness, are truly appealing.

Thanks to the abundant water resources and fertile soil of Lake Kasumigaura, delicious lotus roots loved throughout Japan are cultivated.

#Kasumigaura #LotusRoot #Lotus #Ibaraki' where id = 'gHBkKdhdkXpqHaJiAQ0kX';
