update content_bodies set title = '【絶景茨城／日本遺産】弘道館［4K］茨城県水戸市｜VISIT IBARAKI, JAPAN', description = '【撮影日：2015.5.27】
茨城県水戸市にある国指定特別史跡・重要文化財、弘道館。1842年、水戸藩第９代藩主徳川斉昭によって開設された日本最大の藩校です。最後の将軍徳川慶喜も幼少期にこの場所で学び、大政奉還後に謹慎生活を送りました。今回は実物の「鳥瞰図」（ちょうかんず）や孔子廟の内部、八卦堂に収められている弘道館記碑など普段は見ることのできない部分を映像に納めることができました。

詳細はこちら
http://www.koen.pref.ibaraki.jp/park/kodokan01.html

もっと茨城の観光地を見たい方は
http://www.ibakira.tv/archive/visitibaraki/' where id = 'qoav0ySx79osxCDWUg-vJ';
update content_bodies set title = '[Spectacular Ibaraki / Japan Heritage] Kodokan [4K] Mito City, Ibaraki Prefecture | VISIT IBARAKI, JAPAN', description = '[Date of filming: 2015.5.27] Kodokan, a nationally designated special historic site and important cultural property located in Mito City, Ibaraki Prefecture. Established in 1842 by Tokugawa Nariaki, the 9th lord of the Mito domain, it is the largest domain school in Japan. The last shogun, Tokugawa Yoshinobu, also studied at this location during his childhood and lived in seclusion here after the restoration of imperial rule. This time, we were able to capture footage of parts that are usually not visible, such as the actual ''bird''s-eye view'' (chōkanzu), the interior of the Confucius Temple, and the monument of Kodokan housed in the Hakkadō.

For more details, visit
http://www.koen.pref.ibaraki.jp/park/kodokan01.html

If you want to see more tourist spots in Ibaraki,
