Since ancient times, Oosugi Shrine in Inashiki City, Ibaraki Prefecture has been revered as ''Anba-sama,'' gathering the faith of the people. It is still known today for its miracles and traditions, and is recognized as Japan''s only ''Yume Musubi Daimyojin.'' 
