update content_bodies set title = '【絶景茨城／祝！ラムサール条約登録】涸沼［4K］茨城県茨城町｜VISIT IBARAKI, JAPAN', description = '【撮影日　2015.5.11】
海水と淡水が混じり合う全国的にも希少な汽水湖、涸沼。茨城県のほぼ中央部に位置し、茨城町、鉾田市、大洗町にまたがっています。その流域は多くの動植物が生息する貴重な生態系となっており、その恵みは地元の水産業を盛んにしています。

絶景茨城シリーズはこちら
https://www.youtube.com/playlist?list=PLTFO1tp2jqZ0XUg99QVYMQSlWqKaRurju' where id = 'hSPWjpSuYlFVOWSqwDgD5';
update content_bodies set title = '[Spectacular Ibaraki / Congratulations! Ramsar Convention Registration] Lake Kasumigaura [4K] Ibaraki Prefecture, Ibaraki Town | VISIT IBARAKI, JAPAN', description = '[Date of filming: 2015.5.11] 
Lake Kasumigaura, a rare brackish lake in Japan where seawater and freshwater mix. It is located almost in the center of Ibaraki Prefecture, spanning Ibaraki Town, Hokota City, and Oarai Town. Its watershed is a precious ecosystem that is home to many plants and animals, and its bounty supports the local fishing industry.

For the Spectacular Ibaraki series, click here: 
https://www.youtube.com/playlist?list=PLTFO1tp2jqZ0XUg99QVYMQSlWqKaRurju' where id = '_XgWl6wlfa6z-BRnnjEdD';
update content_bodies set title = '【絶景茨城】つつじ［4K］茨城県笠間市｜VISIT IBARAKI, JAPAN', description = '【撮影日　2015.4.27】
春の笠間つつじ公園を彩る約8500株ものつつじ。空の青、山の緑、つつじの赤が織りなす春の笠間の絶景は必見です。「笠間つつじまつり」では野点茶会やお囃子の演奏などのイベントも催され、沢山の観光客で賑わいます。

詳細はこちら
http://www.city.kasama.lg.jp/page/dir002973.html

