update content_bodies set title = '[Spectacular Ibaraki] Azalea [4K] Kasama City, Ibaraki Prefecture | VISIT IBARAKI, JAPAN', description = '[Date of filming: April 27, 2015] 
About 8,500 azaleas color the spring Kasama Azalea Park. 
The breathtaking scenery of spring in Kasama, woven together by the blue sky, green mountains, and red azaleas, is a must-see. 
During the ''Kasama Azalea Festival,'' events such as outdoor tea ceremonies and traditional music performances are held, attracting many tourists. 

For more details, visit here: 
http://www.city.kasama.lg.jp/page/dir002973.html 

