update content_bodies set title = '[Spectacular Ibaraki] Nanohana [4K] Sakai Town, Ibaraki Prefecture | VISIT IBARAKI, JAPAN', description = '[Date of filming: 2015.4.16]
Every spring, a beautiful carpet of yellow nanohana (rapeseed flowers) appears along the riverbank in Sakai Town, Ibaraki Prefecture.
At the ''Sakai Nanohana Festival'' held at this location, you can enjoy the scenery of the nanohana fields spreading along the riverbank while riding on a Takase-bune ferry.

For more details, visit
