update content_bodies set title = '【絶景茨城】桜［4K］茨城県日立市｜VISIT IBARAKI, JAPAN', description = '【撮影日　２０１５．４．６】
茨城県日立市にある「かみね公園」と日立駅前「平和通り」は日本のさくら名所百選にも選出されています。
海と山の間を駆け抜ける風が美しい桜の花を揺らし,その街に生きる人々の生活を彩り,茨城県内外から観光客を魅きつけて街を賑やかにします。
毎年春には日立さくらまつりが開催され,ユネスコ無形文化遺産に登録された山車「日立風流物」が桜の景色に迫力を与えます。
詳細はこちら
http://www.ibarakiguide.jp/seasons/sakura/s_hitachi.html
もっと茨城の観光地を見たい方は
http://www.ibakira.tv/archive/visitibaraki/' where id = 'WGB23h2ZQG35JVIBktyXM';
update content_bodies set title = '[Spectacular Ibaraki] Cherry Blossoms [4K] Hitachi City, Ibaraki Prefecture | VISIT IBARAKI, JAPAN', description = '[Date of filming: 2015.4.6] 
"Kamine Park" in Hitachi City, Ibaraki Prefecture, and "Heiwa Street" in front of Hitachi Station have been selected as one of Japan''s top 100 cherry blossom spots. 
The wind that rushes between the sea and the mountains sways the beautiful cherry blossoms, coloring the lives of the people living in the city and attracting tourists from both inside and outside Ibaraki Prefecture, bringing vibrancy to the town. 
Every spring, the Hitachi Cherry Blossom Festival is held, and the float "Hitachi Furuibutsu," registered as a UNESCO Intangible Cultural Heritage, adds grandeur to the cherry blossom scenery. 
For more details, visit 
http://www.ibarakiguide.jp/seasons/sakura/s_hitachi.html 
If you want to see more tourist spots in Ibaraki, visit 
http://www.ibakira.tv/archive/visitibaraki/' where id = 'EFqNaWCuGv484ZHQ7vfUF';
update content_bodies set title = '【絶景茨城】桜［4K］茨城県つくばみらい市｜VISIT IBARAKI, JAPAN', description = '【撮影日　２０１５．４．２】

つくばみらい市には、関東三大堰の一つ「福岡堰」があります。福岡堰は桜の名所としても有名で、毎年「福岡堰さくらまつり」が開催されます。
茨城観光100選にも選定され、約600本の桜が1.8ｋｍの遊歩道沿いに咲き誇る桜のトンネルを是非ご覧ください。

また、市民の憩いの場でもある、きらくやまふれあいの丘は、春には施設入口前の桜並木の回廊が見事な姿を見せてくれます。


もっと茨城の観光地を見たい方は
http://www.ibakira.tv/archive/visitibaraki/' where id = 'fVLcMb6UhXyq6yQL2oe17';
update content_bodies set title = '[Spectacular Ibaraki] Cherry Blossoms [4K] Tsukuba Mirai City, Ibaraki Prefecture | VISIT IBARAKI, JAPAN', description = '[Date of filming: 2015.4.2]

In Tsukuba Mirai City, there is one of the three major dams in Kanto, the ''Fukuoka Dam.'' The Fukuoka Dam is also famous as a cherry blossom viewing spot, and every year the ''Fukuoka Dam Cherry Blossom Festival'' is held.
It has been selected as one of Ibaraki''s top 100 tourist attractions, and you can see a tunnel of cherry blossoms with about 600 trees blooming along a 1.8 km promenade.

Additionally, Kirakuyama Fureai Hill, which is a place for citizens to relax, showcases a stunning corridor of cherry trees in spring at the entrance of the facility.

For more Ibaraki tourist spots, visit
http://www.ibakira.tv/archive/visitibaraki/' where id = 'q9n0K_9CGEzQqzvam3ZkD';
update content_bodies set title = '【絶景茨城】常陸秋そば ［4K］茨城県常陸太田市 | VISIT IBARAKI,JAPAN', description = '「常陸秋そば」は、茨城が全国に誇るブランド品種。香り、味わいに優れ、通をも唸らせるほどの逸品です。1978年に旧・金砂郷町（常陸太田市）の在来種から高品質種が選抜され、育成されました。その後は県内各地で栽培されるようになり、常陸太田市、常陸大宮市、稲敷市、土浦市、筑西市、結城市、下妻市などが主な産地になっています。合わせて「そばまつり」も各地で開催されています。常陸秋そばは、秋の茨城の風物詩となっています。


絶景茨城
https://www.youtube.com/playlist?list=PLTFO1tp2jqZ0XUg99QVYMQSlWqKaRurju

Visit Ibaraki,Japan
https://www.youtube.com/playlist?list=PLTFO1tp2jqZ3UCGvINWxTmZhTLgLzOPPM' where id = 'MVD_Icozc1qrqaTjl2JwE';
update content_bodies set title = '[Breathtaking Ibaraki] Hitachi Aki Soba [4K] Hitachi Ota City, Ibaraki Prefecture | VISIT IBARAKI, JAPAN', description = '"Hitachi Aki Soba" is a brand variety that Ibaraki proudly boasts nationwide. It excels in aroma and flavor, making it a masterpiece that even connoisseurs rave about. In 1978, high-quality strains were selected and cultivated from the local variety in the former Kinasagō Town (Hitachi Ota City). Since then, it has been cultivated in various regions of the prefecture, with Hitachi Ota City, Hitachi Ōmiya City, Inashiki City, Tsuchiura City, Chikusei City, Yūki City, and Shimotsuma City being the main production areas. Additionally, "soba festivals" are held in various locations. Hitachi Aki Soba has become a seasonal symbol of autumn in Ibaraki.' where id = 'PCI3ejbl_H4kFvXaHbztR';
