update content_bodies set title = '松山城天守閣に行ってきました！', description = 'ここは、愛媛県松山市にある松山城です。松山城には、加藤嘉明の鎧や当時使われていた武器が展示されています。その他にも、武装服を試着できたり、松山城小天守復興の様子のビデオを視聴することもできます。そして、天守閣では360°のパノラマを見ることができます！RyoFさんが松山城入口までの景色を撮影しております！→https://youtu.be/T1l3eHh-TaQ' where id = 'ZyLPc86565TPrRt0rGI_v';
update content_bodies set title = 'I visited Matsuyama Castle''s Main Keep!', description = 'This is Matsuyama Castle located in Matsuyama City, Ehime Prefecture. Matsuyama Castle displays armor worn by Kato Yoshiaki and weapons used at that time. Additionally, you can try on armored clothing and watch a video of the restoration of the Matsuyama Castle''s small keep. Furthermore, you can enjoy a 360° panorama from the main keep! RyoF has captured the scenery leading to the entrance of Matsuyama Castle! → https://youtu.be/T1l3eHh-TaQ' where id = 'TxFWoGahanKa6ofC1PuvN';
update content_bodies set title = '今治城に行ってきました！(本丸跡編)', description = 'ここは、愛媛県今治市にある今治城です。詳しい情報はこちら！→http://museum.city.imabari.ehime.jp/imabarijo/ 天守閣編→https://youtu.be/Rzlk_lNj2o4' where id = 'xNijfEdVIV3n0xVgbpfyr';
update content_bodies set title = 'I visited Imabari Castle! (Main Keep Ruins Edition)', description = 'This is Imabari Castle located in Imabari City, Ehime Prefecture. For more detailed information, click here! → http://museum.city.imabari.ehime.jp/imabarijo/ Main Keep Edition → https://youtu.be/Rzlk_lNj2o4' where id = 'G2HR6yY1MXHouTlv5m67x';
update content_bodies set title = '今治城に行ってきました！(天守閣編)', description = 'ここは、愛媛県今治市にある今治城です！今回は、天守閣を撮影しており！詳しい情報はこちら！→http://museum.city.imabari.ehime.jp/imabarijo/ 本丸跡編→https://youtu.be/7DIJ32CeSvI' where id = '4lxZTzF_heuKHujk66owv';
update content_bodies set title = 'I visited Imabari Castle! (Tenshukaku Edition)', description = 'This is Imabari Castle located in Imabari City, Ehime Prefecture! This time, I was filming the tenshukaku! For more detailed information, click here! → http://museum.city.imabari.ehime.jp/imabarijo/ Main Keep Ruins Edition → https://youtu.be/7DIJ32CeSvI' where id = 'Rc-5O-mtas7HnZYhXxdfq';
update content_bodies set title = '高知城に行ってきました！', description = 'ここは、高知県高知市丸ノ内１丁目２−２−１にある高知城です。 詳しい情報はこちら！→http://kochipark.jp/kochijyo/ そしてこの動画の最後には、高知県高知市の日曜市を撮影しております。 日曜市についての詳しい情報はこちら！→http://www.city.kochi.kochi.jp/soshiki/39/nichiyouichi.html' where id = 'aP5XTw8AlAgHKMslmk4xs';
update content_bodies set title = 'I visited Kochi Castle!', description = 'This is Kochi Castle located at 1-2-2-1 Marunouchi, Kochi City, Kochi Prefecture. For more information, click here! → http://kochipark.jp/kochijyo/ And at the end of this video, I have filmed the Sunday Market in Kochi City, Kochi Prefecture. For more information about the Sunday Market, click here! → http://www.city.kochi.kochi.jp/soshiki/39/nichiyouichi.html' where id = 'fvQMsMJw_ivWbn8JYDwBb';
update content_bodies set title = '大洲城に行ってきました！', description = 'ここは、愛媛県大洲市大洲９０３にある大洲城です。大洲城には、2004年に復元された天守をはじめ、国指定重要文化財に選定された4棟の櫓があります。そしてこの動画の最後には、愛媛県松山市を流れる宮前川にいたコガモを撮影しております。' where id = 'UgazhgtL0BqFmXqwD2l_G';
update content_bodies set title = 'I visited Ozu Castle!', description = 'This is Ozu Castle, located at 903 Ozu, Ozu City, Ehime Prefecture. Ozu Castle features a main keep that was restored in 2004, along with four turrets designated as Important Cultural Properties by the national government. At the end of this video, we also captured footage of a female teal that was in the Miyamae River flowing through Matsuyama City, Ehime Prefecture.' where id = 'dZE2A0AHXnTS0M5tWJveI';
update content_bodies set title = '大洲城 歓迎はたふり', description = 'このイベントは、愛媛県大洲市大洲９０３にある大洲城で行われている「大洲城 歓迎はたふり」です！大洲城では、JR四国の観光列車「伊予灘ものがたり」が鉄橋をゆっくり渡るとき、大洲城本丸からのぼり旗を振って、歓迎しています。開催日は毎週土・日・祝日、時間は15:16頃と16:25頃の２回です。参加無料です。 そしてこの動画の最後には、愛媛県松山市を流れる宮前川にいたコガモを撮影しております。' where id = 'Gaawt3aIRy2Fi5_VQS4HK';
update content_bodies set title = 'Ozu Castle Welcome Hataburi', description = 'This event is called ''Ozu Castle Welcome Hataburi'' and takes place at Ozu Castle located at 903 Ozu, Ozu City, Ehime Prefecture! At Ozu Castle, we wave welcome flags from the main keep when the JR Shikoku sightseeing train ''Iyodan Monogatari'' slowly crosses the bridge. The event is held every Saturday, Sunday, and public holiday, with two sessions at around 15:16 and 16:25. Participation is free. At the end of this video, we also captured a female duck (Kogamo) in the Miyamae River flowing through Matsuyama City, Ehime Prefecture.' where id = 'vI567CreraUlUGnkZ6KYd';
update content_bodies set title = '名古屋おもてなし武将隊の演武を見てきました！', description = 'この演武は、平成30年(2018年)1月28日に堀之内と松山城で行われた「第５回 全国城サミットin松山」です。この演武では、織田信長と豊臣秀吉と徳川家康の楽しい話を聞いて楽しめます！そして、演武終了後は、織田信長と豊臣秀吉と徳川家康と一緒に写真撮影ができます！ 丸亀城鉄砲隊の演武はこちら！→https://youtu.be/lgCToSMmet4' where id = 'm7ZWoAZh_W5ayor2R9G_p';
update content_bodies set title = 'I went to see the performance of the Nagoya Omotenashi Busho-tai!', description = 'This performance took place on January 28, 2018, at Horinouchi and Matsuyama Castle during the "5th National Castle Summit in Matsuyama." In this performance, you can enjoy fun stories about Oda Nobunaga, Toyotomi Hideyoshi, and Tokugawa Ieyasu! After the performance, you can take photos with Oda Nobunaga, Toyotomi Hideyoshi, and Tokugawa Ieyasu! You can see the performance of the Marugame Castle Gun Corps here! → https://youtu.be/lgCToSMmet4' where id = '5_PjUwqjjUcZ5O55sOxrJ';
update content_bodies set title = '丸亀城鉄砲隊の演武を見てきました！', description = 'このイベントは、愛媛県松山市の堀之内で行われた「第５回 全国城サミットin松山」の丸亀城鉄砲隊の演武です。この演武では、安土桃山時代に使われていた火縄銃の迫力を感じることができます。実際の安土桃山時代の迫力を感じてみて下さい！ 名古屋おもてなし武将隊の演武はこちら！→https://youtu.be/nSs7-jqvqVQ' where id = 'ckrN_EDTxReXvrHgUkZuQ';
update content_bodies set title = 'I Went to See the Demonstration of the Marugame Castle Gun Corps!', description = 'This event is the demonstration of the Marugame Castle Gun Corps at the ''5th National Castle Summit in Matsuyama'' held in Horinouchi, Matsuyama City, Ehime Prefecture. In this demonstration, you can experience the power of the matchlock guns used during the Azuchi-Momoyama period. Feel the actual intensity of the Azuchi-Momoyama period! You can watch the performance of the Nagoya Hospitality Samurai Corps here! → https://youtu.be/nSs7-jqvqVQ' where id = 'uFAbY7tBvy4iEfIMo-uor';
update content_bodies set title = '宇和島城に行ってきました！(登城編)', description = 'ここは、愛媛県宇和島市にある宇和島城です。宇和島城は、標高80mの丘上に築かれた平山城です。伊達氏2代宗利が大改修し現在の形になってます。天守閣は国指定重要文化財です。 天守編→https://youtu.be/niqMlrwPq6M

#宇和島城 #愛媛県宇和島市 #伊達藩' where id = '2yUZ8Znqxo-z9LiAHAuGg';
update content_bodies set title = 'I visited Uwajima Castle! (Castle Climbing Edition)', description = 'This is Uwajima Castle located in Uwajima City, Ehime Prefecture. Uwajima Castle is a flatland castle built on a hill with an elevation of 80m. It was significantly renovated by the second generation of the Date clan, Muneyoshi, to take its current form. The main keep is designated as an important cultural property by the country. Main keep edition → https://youtu.be/niqMlrwPq6M

#UwajimaCastle #UwajimaCity #DateDomain' where id = '9xi_CqT8e4MEZ_6TPox4j';
update content_bodies set title = '愛媛県四国中央市「川之江城」に行ってみた！', description = 'ここは、愛媛県四国中央市にある川之江城です。川之江は、昭和61年(1986年)に天守閣、涼櫓、櫓門、空塀などが整備された城で、瀬戸内の島々の眺望が素晴らしく、桜の名所として多くの観光客が訪れている場所です。皆さんも是非行ってみて下さい。

#川之江城 #城 #愛媛県四国中央市' where id = 'wnHtG1iFi79QOAEaydnQz';
update content_bodies set title = 'I Went to Kawanoe Castle in Shikokuchuo City, Ehime Prefecture!', description = 'This is Kawanoe Castle located in Shikokuchuo City, Ehime Prefecture. Kawanoe is a castle that was developed in 1986 (Showa 61) with its main keep, cool turret, turret gate, and sky walls, offering a wonderful view of the islands of the Seto Inland Sea. It is a famous cherry blossom spot that attracts many tourists. Please make sure to visit!' where id = 'WE1_jQeZcHqpAUvmpTx5a';
update content_bodies set title = '【しまなみ海道伯方島】探索！木浦城跡(伯方ふるさと歴史公園)！', description = 'ここは、愛媛県今治市伯方町にある木浦城跡(伯方ふるさと歴史公園)です。木浦城跡(伯方ふるさと歴史公園)には、城や古墳があり、まさに歴史を感じることのできる公園です。

#しまなみ海道 #伯方島 #愛媛県今治市' where id = 'DxtTyuqWOYGJHzzFXEb8t';
update content_bodies set title = 'Exploring the Kiu Castle Ruins (Hakaba Furusato History Park) on Shimanami Kaido Hakata Island!', description = 'This is the Kiu Castle Ruins (Hakaba Furusato History Park) located in Hakaba Town, Imabari City, Ehime Prefecture. The Kiu Castle Ruins (Hakaba Furusato History Park) features a castle and ancient tombs, making it a park where you can truly feel the history.' where id = '4Kr3MRZ0UjiZo5qcmJ8kE';
update content_bodies set title = '天守閣からの景色は絶景！岩国城を探索してみた！', description = 'ここは、山口県岩国市にある岩国城です。山頂からの景色と日本刀の展示で有名な城です。

#山口県岩国市 #城 #おしろ #お城 #景色 #絶景 #天守閣' where id = 'n3TxdRAvN-QOADkEnEEVa';
update content_bodies set title = 'The view from the castle tower is breathtaking! Exploring Iwakuni Castle!', description = 'This is Iwakuni Castle located in Iwakuni City, Yamaguchi Prefecture. It is famous for its views from the mountaintop and its display of Japanese swords.' where id = 'ayM2SN1Q61bi8wv7GWD2k';
update content_bodies set title = '審査員特別賞「立ち上がろう雲仙市」un film de Ryuji Shibata', description = '第17回NCCふるさとCM大賞　受賞作品
