update content_bodies set title = 'A Female College Student Beginner in Camping Tried Solo Camping in Aso. [Grilled Tomato Edition]', description = 'Enjoying delicious ingredients in the great outdoors with ''Aso Camp''

Thank you for watching the video.
First, what is ''Aso Camp''...
As the name suggests, it is camping that can be done in Aso, Kumamoto Prefecture, located in Kyushu. We deliver a special camping video that you can only experience in Aso, with flavors that cannot be tasted anywhere else!

―Online Shop ASOMO―  https://aso-asomo.com/
In this project, we are particular about the ingredients used in camp cooking.
Here are the products purchased this time from the online shop ASOMO.
▶King Tomato: [Sudou Farm]  https://aso-asomo.com/?pid=152514736
Sales Period: June to October (this is just a guideline)

Please also enjoy the exquisite products of Aso!

―Campsite―
For the second time, I did solo camping at ''Aso Hotkan'' in Kitazakanari, Aso City, just like the first time.
It is a special campsite that is not easily accessible to the general public, where you can enjoy a slightly different time and atmosphere.
[Aso Hotkan]  https://aso-hotkan.com/

―Enjoying Aso with Corgi Dog Rito!―
