update content_bodies set title = '【バラ満開】秋の薔薇まつり in ASO MILK FACTORY', description = '阿蘇市小里にある観光施設”ASO MILK FACTORY”のローズガーデンでは、温室で育てられたバラの花が見頃を迎えています。

秋のバラは春に比べて花の数は少ないですが、香りが強く、色味の深い艶っぽい花を咲かせるのが特徴です。

開催期間：令和３年10月9日(土)～令和３年11月7日(土)
入場料：無料
◎期間中、売店にてバラの苗・肥料の販売
◎カフェでは特別メニューの薔薇バウムソフト販売
◎レストランでは食後のジェラートに薔薇付き

