update content_bodies set title = '[Full Bloom] Autumn Rose Festival at ASO MILK FACTORY', description = 'In the rose garden of the tourist facility ''ASO MILK FACTORY'' located in Kozaki, Aso City, the roses grown in the greenhouse are in full bloom.

Autumn roses have fewer flowers compared to spring, but they are characterized by their strong fragrance and deep, lustrous colors.

Event Period: October 9, 2021 (Saturday) to November 7, 2021 (Saturday)
Admission Fee: Free
◎ During the event, rose seedlings and fertilizers will be sold at the shop.
◎ The café will offer a special menu featuring rose Baumkuchen soft serve.
◎ The restaurant will serve gelato with roses after meals.

