update content_bodies set title = '【大自然4K】「阿蘇 中岳火口」高画質 癒し映像', description = '自然豊かな阿蘇の風景を4Kカメラで撮影するシリーズ『SCENE of the ASO』。

vol.2は、力強い大地の鼓動が感じられる「中岳火口」です。

阿蘇の人々は千年以上前から、阿蘇火山と共に生きてきました。中岳の火山活動は、阿蘇の広大な草原や温泉・地下水といった恵みを私たちに与え、時には自然の驚異を教えてくれます。

2021年10月20日に噴火した中岳は、現在噴火警戒レベル３の入山規制のため火口見学ができませんが、2021年8月と9月に、標高1,506メートルの中岳山頂からと東峰展望所、そして中岳第1火口の火口縁から撮影した映像をお楽しみください。

