update content_bodies set title = '[Nature 4K] ''Aso Nakadake Crater'' High-Quality Healing Video', description = 'A series capturing the rich landscapes of Aso with a 4K camera, ''SCENE of the ASO''.

Vol.2 features the ''Nakadake Crater'', where you can feel the powerful heartbeat of the earth.

The people of Aso have lived alongside the Aso volcano for over a thousand years. The volcanic activity of Nakadake provides us with the blessings of Aso''s vast grasslands, hot springs, and underground water, and sometimes teaches us the wonders of nature.

Currently, due to the volcanic alert level 3 and entry restrictions, we cannot visit the crater, which erupted on October 20, 2021. However, please enjoy the footage taken from the summit of Nakadake at an elevation of 1,506 meters, the Higashimine Observatory, and the crater rim of Nakadake''s first crater in August and September 2021.

