Vol.3 features the sea of clouds in Aso, where a fantastical landscape unfolds before your eyes.

From autumn to winter, the Aso valley welcomes the season of sea of clouds. It occurs in the early morning before dawn when high humidity, radiative cooling of the surface, and calm weather conditions coincide.

Filmed in November 2021 at the popular spot ''Sorafune no Sanbashi'' in Aso City, Tagoyama.

Watching it in fast motion enhances the enjoyment of the flowing clouds.

