update content_bodies set title = '【大自然4K】「阿蘇 しめ縄作り」高画質 癒し映像', description = '自然豊かな阿蘇の風景を4Kカメラで撮影するシリーズ『SCENE of the ASO』。

vol.4は、年末の阿蘇の風物詩、阿蘇神社のしめ縄作りです。

阿蘇神社の拝殿に飾られる大しめ縄は、30年以上前から阿蘇神社の氏子らでつくる「一の宮町大注連縄伝承会」が毎年奉納しています。

今年は10月から本格的に準備を始め、もち米の稲わらを編み込んで作られた長さ7.5メートル、重さ150キロの大しめ縄を17人の会員で完成させました。

2021年12月8日に阿蘇神社に奉納され、今年6月に熊本地震からの復旧工事が完了したばかりの新しい拝殿に青々としたきれいな大しめ縄が飾られました。

拝殿が再建されて迎える初めてのお正月、ぜひ初詣は阿蘇神社にお越しください。


