update content_bodies set title = '酒の國いわて ～南部杜氏の郷～', description = 'およそ400年前、近江商人が清酒の醸造技術をこの地に持ち込み、本格的な酒造りが始まったと言われています。盛岡地域には昔ながらの趣ある９つもの酒蔵が集積し、今に受け継がれる南部杜氏の伝統の技を活かしながら、新しい酒造りへの努力と挑戦が続けられています。杜氏や蔵人たちの情熱と愛情に溢れる岩手の酒造りをご覧ください。そして、岩手のお酒で乾杯しましょう。ようこそ!　酒の國いわてへ' where id = 'mBfnhQqQBvEOkSWdfkwfQ';
update content_bodies set title = 'The Land of Sake Iwate - Home of Nanbu Toji', description = 'About 400 years ago, it is said that merchants from Omi brought the brewing techniques of sake to this region, marking the beginning of authentic sake production. In the Morioka area, there are nine traditional sake breweries that have been preserved over the years, and efforts and challenges towards new sake production continue while utilizing the traditional skills of Nanbu Toji that have been passed down to this day. Experience the passionate and loving sake-making of Iwate, filled with the enthusiasm of the toji and kurabito. And let''s raise a glass with Iwate''s sake. Welcome to The Land of Sake Iwate!' where id = 'e31Y4xOm_1bMc5WnCiXVH';
