update content_bodies set title = 'SADO NO KIWAMI Vol. 1: 究極の佐渡の滝 -十郎滝に挑む-', description = '「SADO NO KIWAMI」、つまり究極の佐渡は、佐渡に住み、佐渡を愛し、佐渡を極めた人々を通じて、佐渡の冒険観光を紹介します。
滝のガイドである石塚裕之は滝をよく知っており、ツアーを通じてその魅力を伝えます。
彼を通じて、他では味わえない佐渡での究極の体験を紹介します！
* 冒険観光は、「自然、活動、文化」の3つの要素のうち少なくとも2つを含む体験を通じて、場所の魅力をより深く楽しむことができる観光の一形態です！

ブログ：https://niigata-kankou.or.jp/blog/1101
#niigata #sado #adventuretourism #waterfall' where id = 'KPkE9UUZ_qTywzIkNVlza';
update content_bodies set title = 'SADO NO KIWAMI Vol. 1: The Ultimate Sado Waterfall -Tackling Juro Falls-', description = '“SADO NO KIWAMI”, or Ultimate Sado, showcases adventure tourism on Sado through those who live in Sado, love Sado, and have mastered Sado.
 The waterfall guide Ishizuka Hiroyuki knows the waterfalls well and shows their charm with tours. Through him, we introduce to you an ultimate experience on Sado that is not found anywhere else!
 * Adventure tourism is a form of tourism that lets you enjoy the charms of a place more deeply by having an experience consisting of at least two of the three elements:“nature, activity, and culture”!

Blog：https://niigata-kankou.or.jp/blog/1101
#niigata #sado #adventuretourism #waterfall' where id = 'MpCKczNQpQiZsa8ThjDKt';
update content_bodies set title = '愛媛県 宇和島市 和霊神社(2019.9.19)', description = '漁業を中心に広く産業の神として、中四国で崇められている和霊信仰。その総本山といえるのが和霊神社です。愛媛県宇和島市にあります。雰囲気のある神社でパワーを貰えそうですが観光のお客様は少なめです。是非、いらしてくださいね。

宇和島市観光物産協会 和霊神社
http://www.uwajima.org/spot/index3.html
宇和島市HP
https://www.city.uwajima.ehime.jp/
ご宿泊は、宇和島オリエンタルホテル
https://www.oriental-web.co.jp/uwajima/' where id = '-Hd6dt4NGmgP7Eu275-Il';
update content_bodies set title = 'Uwajima City, Ehime Prefecture, Warei Shrine (2019.9.19)', description = 'Warei faith, revered as the god of industry centered around fishing, is widely worshipped in the Chugoku and Shikoku regions. The Warei Shrine can be said to be its main temple. It is located in Uwajima City, Ehime Prefecture. The shrine has a charming atmosphere that seems to offer power, but there are relatively few tourists. Please do come and visit.

Uwajima City Tourism and Products Association Warei Shrine
http://www.uwajima.org/spot/index3.html
Uwajima City Official Website
https://www.city.uwajima.ehime.jp/
For accommodation, Uwajima Oriental Hotel
https://www.oriental-web.co.jp/uwajima/' where id = '6zavwB1K9ObsuS57OxclY';
update content_bodies set title = '大佐渡石名天然杉遊歩道【夏編】', description = '大佐渡山脈の北部にある県有林石名団地には、特異な形状の巨杉が生育しています。
新潟県では、この雄大な天然杉を安全にご覧いただけるように遊歩道を整備しました。
起伏の少ないコースなので、子どもの自然学習の場としても安心してお薦めできます。' where id = '6gijFa0OLGDA8ADxqxia5';
update content_bodies set title = 'Ogasawara Ishina Natural Cedar Walking Path [Summer Edition]', description = 'In the Ishina district of the prefectural forest located in the northern part of the Ogasawara mountain range, unique-shaped giant cedars are growing.
In Niigata Prefecture, a walking path has been developed to allow visitors to safely view these magnificent natural cedars.
The course has little elevation change, making it a safe and recommended place for children''s nature learning.' where id = '_xvoS0tzAP0cjCIwUfJZH';
update content_bodies set title = '大佐渡石名天然杉遊歩道【霧編】', description = '大佐渡山脈の北部にある県有林石名団地には、特異な形状の巨杉が生育しています。
