update content_bodies set title = '愛媛県北宇和郡松野町 おさかな館・ぽっぽ温泉(2019.10.14)', description = '愛媛県北宇和郡松野町 おさかな館・ぽっぽ温泉のご紹介動画です。いくつか動画が消えてしまったため内容が薄々ですがご勘弁ください。西日本豪雨災害で甚大な被害を受けましたが復旧し営業しています。
山の中の淡水水族館、駅舎一体のぽっぽ温泉にぜひ遊びに来て下さい。

