update content_bodies set title = '5/5大洲編 伊予灘ものがたり 車で追いかける(2022.5.5)', description = '今回は並走することを目的に5月5日、大洲編の伊予灘ものがたりを撮影しました。
360°カメラを車外に配置して撮高は運任せで安全第一に他の車の邪魔にならないように走りました。
まぁまぁな仕上がりになったかなと思います。

コメント募集：2022年5月5日、大洲編に乗っていた方のコメントお待ちしてます(^^)

撮影
 ：Insta360 one X2
編集
：Insta360 Stdio2022
：Final Cut PRO' where id = 'St43OcPRWpNLYP1pMXbjD';
update content_bodies set title = '5/5 Ozu Edition Iyo-nada Story Pursued by Car (2022.5.5)', description = 'This time, on May 5th, I filmed the Iyo-nada story in the Ozu edition with the aim of running alongside it.
I placed a 360° camera outside the car and prioritized safety while ensuring I didn''t interfere with other vehicles.
I think it turned out fairly well.

Comments Wanted: I''m looking forward to comments from those who were on the Ozu edition on May 5, 2022 (^^)

Filming
: Insta360 one X2
Editing
: Insta360 Studio 2022
: Final Cut PRO' where id = 'I03T0O4RTRtTwUNRyNrrQ';
