update content_bodies set title = 'うわじま牛鬼祭り 海上打上花火(2023.7.23)', description = 'うわじま牛鬼祭りの海上打上花火を見てきました。
8:30から9:10までの約40分間の花火でしたが途中、メインカメラがトラブったり熱暴走で撮影がストップしたりと散々な40分間でしたが撮れていた映像を時系列に繋げて9分弱の動画にまとめました。

花火の感想としては全体的に位置が低いなぁと思っていたら画角を遥かに飛び越えた高い位置へ上がったりとほんと撮影している人泣かせの演出だったような気がします。一応360°カメラで撮影していたため画角を外れることはなかったものの編集の上では見切らなければならないところが多々ありました。構成もも今ひとつだったかなぁ。
数年ぶりの開催だったんで仕方ないところもあるのかもしれません。来年に期待します。

撮影機器：Insta360 one X2' where id = '3Y9Kdfs1Pswsz9SR9ZhQl';
update content_bodies set title = 'Uwajima Ushi-Oni Festival Fireworks Display (2023.7.23)', description = 'I went to see the fireworks display at the Uwajima Ushi-Oni Festival.
It was about a 40-minute fireworks show from 8:30 to 9:10, but during that time, the main camera had some troubles and stopped recording due to overheating, making for a challenging 40 minutes. However, I managed to stitch together the footage that was captured into a video just under 9 minutes long.

As for my impressions of the fireworks, I thought they were generally positioned low, but then some went up to heights that far exceeded the frame, which seemed to be a bit of a challenge for the person filming. Although I was using a 360° camera, so I didn''t miss the frame, there were many parts in the editing that had to be cropped out. The overall composition could have been better, I think.
It might be understandable since it was the first event in several years. I look forward to next year.

Filming equipment: Insta360 One X2' where id = 'Osf8_e1lHMq9m5dIATh2E';
update content_bodies set title = '大洲川まつり 花火大会 夏の陣(2023.8.3)', description = '大洲市の花火大会に行ってきました。
人も多く賑わっていました。
人混みが苦手のため遠くから橋越しの撮影になっています。
約45分ほどの打ち上げ時間でした。
Insta360OneX2よりはiPhone14の画質は良いですね。ただ。思った上に花火が低くて最初に設定していた画角が無駄だったんでトリミングしています。
そのせいで画質が・・・



(待機時間、音楽に合わせての打ち上げはカットしています)

撮影機器：iPhone14' where id = 'zTuUXXmn8-D_bJi3PRDyU';
update content_bodies set title = 'Ozu River Festival Fireworks Competition Summer Edition (2023.8.3)', description = 'I went to the fireworks festival in Ozu City.
There were many people and it was lively.
Since I''m not good with crowds, I took photos from a distance over the bridge.
The launch time was about 45 minutes.
The quality of the iPhone 14 is better than that of the Insta360OneX2. However, the fireworks were lower than I expected, so the angle I initially set was wasted, and I had to crop the images.
Because of that, the quality...

(Waiting time and launches synchronized with music have been cut)

