update content_bodies set title = '大洲市 少彦名神社(2023.12.19)', description = '大洲市 少彦名神社に行ってきました。
生憎の雨でしたがどうしても少彦名神社の参籠殿がみたくて足を運びました。
懸作りの足場が立派で見入ってしまいました。

肱川改修工事の影響であまり人が来ないのか本殿は荒れ気味で残念でした。

