update content_bodies set title = '大洲市冨士山公園展望台からの絶景雲海(2023.12.30)', description = '大洲市の冨士山(とみすやま)公園展望台へ行って来ました。
眼下に広がる雲海、なんかいつまでも見てられる。
いやい大洲市外から5分でこんな絶景が見られるなんてほんとビックリです。

10;00前には雲が抜け始め大洲市街が見え始めます。

