update content_bodies set title = '【本編】高知県香南市 四国自動車博物館(2024.7.12)', description = '前々から気になっていた四国自動車博物館へ足を運んできました。
宇和島市から鬼北、檮原経由で高知県香南市へ。時間にして３時間。

