update content_bodies set title = '[Main] Kōnan City, Kōchi Prefecture Shikoku Automobile Museum (2024.7.12)', description = 'I visited the Shikoku Automobile Museum, which I had been curious about for a long time.
I traveled from Uwajima City to Kōchi Prefecture via Kihoku and Tōyama. It took about 3 hours.

The exhibition had many vehicles that are irresistible for supercar enthusiasts.
There was also a limited-time display of the 222D (MR2), which kept me excited throughout the visit.
Personally, I thought the Dino and Crown were the best.

Music: BGMer
