update content_bodies set title = 'Nofuku Pass, Seiyo City, Prefectural Road 45 (2025.4.1)', description = 'The weather isn''t great, but due to the holiday, I went to Nofuku Pass.
Nofuku Pass in Seiyo City can be accessed by entering Prefectural Road 45 from the Seiyo City side of Route 56, and after a short drive, you will reach Nofuku Pass.
The beautiful scenery of the rias coastline, with about 400 cherry blossom trees in full bloom, creates a winding drive that offers a stunning view of the Uwakai Sea and the orange orchards.

BGM: Dried Flowers - If You Call It Love (Unreleased Original Song)
