update content_bodies set title = '宇和島市 遊子水荷浦の段畑(2025.4.30)', description = '4月最終日のお休みは遊子水荷浦の段畑へ行って来ました。
市内から三浦半島方面へ車を約20分ほど走らせれば壮大な段々畑が見えてきます。
宇和島市的には結構推してるのではないかと思いますが観光客の増員には繋がっていないようです。土日祝日には段々畑のふもの駐車場にある「だんだん茶屋」がオープンしているので宇和島鯛めしなど食事を楽しむことができます(営業時間に関しては別途確認願います)

山肌に刻まれた壮大な段々畑で悠久の時を感じてみてはいかがでしょうか。

「だんだん茶屋」ではCD「KISAIYA宇和島」作成前から店内音楽としてみーかんチャンネルで作成した音楽を流していただいているので応援しています。

BGM：ゆすみずがうら(販売中のCD「KISAIYA宇和島」収録曲)
