update content_bodies set title = '天空の城-宇和島城-(AI Music 2025.5.11)', description = '本日はきさいや広場で「宇和島EXPO」が行われておりますが人混み嫌い発動で宇和島城へ。
オリジナル楽曲「天空の城-宇和島城-」の歌詞を完成させるために登りました。
コンパクトだけど雰囲気のあるイメージがある宇和島城をどう表現するか。
とりあえずは過去に遡り武士になった感じで・・・創作。
で、できました。

Xでの予告は女性が歌っていましたがここに登ってまぁ最初は男性ボーカルかなということで変更してます。

BGM：天空の城-宇和島城-(未配信オリジナル楽曲)
