update content_bodies set title = 'Castle in the Sky - Uwajima Castle - (AI Music 2025.5.11)', description = 'Today, the ''Uwajima EXPO'' is being held at Kisaiya Square, but due to my dislike of crowds, I headed to Uwajima Castle.
I climbed up to complete the lyrics for the original song ''Castle in the Sky - Uwajima Castle.''
How to express the compact yet atmospheric image of Uwajima Castle?
For now, I went back in time and felt like a samurai... creating.
And, it’s done.

The preview on X featured a female vocalist, but I thought it would be better to change it to a male vocal since I’m up here.

BGM: Castle in the Sky - Uwajima Castle - (Unreleased Original Song)
