update content_bodies set title = '天空の城 - 宇和島城 - (2025.8.6)', description = '宇和島城に上りました。
この熱い中、よせばいいのに、なんとなく城が見たくて。
上りながら大きな後悔(^^;
暑かった、痩せた、疲れた・・・笑
登りながら歌に合わせたカットを考えつつ登りましたが史料館以降はそれどころじゃなかったです。
暑すぎ。
せっかくなんで「天空の城 - 宇和島城 -」を無限城MixでBGMをアレンジしました。
前半は出陣までの緊張感をイメージしております。
歌はアカペラから始まりオーケストラが寄り添っていくように。
真夏の宇和島城は・・・他の観光客に合わない貸切でした(^^)

BGM：天空の城 - 宇和島城 - (無限城Mix)
