update content_bodies set title = '県南浜街道地域（名取市，岩沼市，亘理町，山元町）観光案内動画（台湾語版）', description = '宮城県仙台地方振興事務所では，東日本大震災で甚大な被害を受けた県南浜街道地域（名取市，岩沼市，亘理町，山元町）に１人でも多くの観光客に足を運んでもらいたいという願いを込め，それぞれの市町が持っている魅力的な自然や観光施設，復興の様子などについて紹介した動画を制作しました。
　ドローンで撮影した迫力ある映像で，県南浜街道地域の魅力を発信していますので，ぜひご覧ください。' where id = 'u_Du7VbkrvG2sk72GB_Of';
