update content_bodies set title = '日本の日光で訪れるべき場所 | 湯滝 | 旅行ガイド', description = '#nikko #yudakifalls #japantravel #japanvlog #visitjapanjp #mybestjapanmoments #japantour

湯滝は、栃木県日光市の奥日光エリアにある滝です。高さ50メートル（164フィート）、幅25メートル（82フィート）で、華厳の滝や竜頭の滝と並ぶ奥日光の三大滝の一つです。日本の100名山の一つである日光白根山の麓に位置する湯ノ湖の南岸から流れ落ちています。湯ノ湖の岸には日光湯元温泉があり、湯ノ湖エリア全体には温泉が点在していますが、湯滝はその名に反して温泉水ではなく冷水が流れています（湯=温水、滝=滝）。滝の水は湯川となり、日本の高地湿原の一つである仙女ヶ原湿原を流れ、竜頭の滝を経て中禅寺湖に流れ込みます。湯滝の側には遊歩道が整備されており、滝の口、盆地、側面など、滝の三つのポイントを観賞することができます。展望デッキから滝の盆地を間近で見ることは特に意義深い体験です。' where id = '0uTuWJBIWKhmGzHcCyKNM';
update content_bodies set title = 'Places to Visit in Nikko Japan | Yudaki Falls | Travel Guide', description = '#nikko #yudakifalls #japantravel #japanvlog #visitjapanjp #mybestjapanmoments #japantour

Yudaki Falls is a waterfall in the Oku-Nikko area of Nikko City, Tochigi Prefecture. Measuring 50 meters (164 feet) high and 25 meters (82 feet) wide, it is one of the three major waterfalls in Oku-Nikko along with Kegon Falls and Ryuzu Falls. It flows down from the south shore of Lake Yuno-ko, which is located at the foot of Mt. Nikko-Shirane, one of Japan''s 100 Major Mountains. There is Nikko Yumoto Onsen on the banks of Lake Yuno-ko, and the entire Yuno-ko area has hot springs all over the place, but it is not hot water but cold water that flows down the Yudaki despite of its name Yudaki aka Yutaki (Yu=hot water, daki/taki=waterfall). The water from the waterfall becomes the River Yukawa, which flows through one of Japan''s most prominent wetland of high elevation, Senjo-gahara Marshland, then flows down the Ryuzu Falls to Lake Chuzenji-ko. A promenade is provided on the side of the Yudaki Falls, from where you can watch three points of the waterfall such as its mouth, basin and side. Watching the waterfall basin up close from the observation deck is expecially significant.' where id = '7PeIZ44ATyrjgWDOblRqg';
update content_bodies set title = 'Chair Lift Ride at Mount Takao (Ascend) | Japan''s Steepest Slope | 高尾山　チェアリフト', description = '#mttakao #chairlift #japan #mttakoadventures #steepestslopeinjapan #mttakaochairlift #japanadventures #mybestjapanmoments #visitjapanjp #viaggiatotravelservices

Mount Takao (高尾山, Takao-san) is a mountain in the city of Hachiōji, Tokyo, Japan. It is protected within Meiji no Mori Takao Quasi-National Park.

Standing 599 metres (1,965 ft) tall and located within an hour of downtown Tokyo, it is a popular hiking spot, with eight hiking courses and more than 2.5 million annual visitors. The Tama Forest Science Garden is also located at the mountain''s base.

THE CHAIR LIFT RIDE

In addition to the cable car Mt. Takao also has a chair lift that you can ride to the midway point of the mountain!
The ride time is about 12 minutes so why not enjoy an aerial trip through the mountains?

The distance from “Sanroku Station” at the foot of the mountain to “Sanjo Station” in the middle is about 872m, which is shorter than the distance the cable car travels (The cable car travels a total of 1,020m).

